  1→//! Init command implementation.
  2→//!
  3→//! The `bivvy init` command initializes project configuration.
  4→
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→
  8→use crate::cli::args::{InitArgs, RunArgs};
  9→use crate::config::CompletedCheck;
 10→use crate::detection::DetectionRunner;
 11→use crate::error::Result;
 12→use crate::registry::builtin::BuiltinLoader;
 13→use crate::registry::template::Template;
 14→use crate::ui::{hints, Prompt, PromptOption, PromptResult, PromptType, UserInterface};
 15→
 16→use super::dispatcher::{Command, CommandResult};
 17→use super::run::RunCommand;
 18→
 19→/// The init command implementation.
 20→pub struct InitCommand {
 21→    project_root: PathBuf,
 22→    args: InitArgs,
 23→}
 24→
 25→impl InitCommand {
 26→    /// Create a new init command.
 27→    pub fn new(project_root: &Path, args: InitArgs) -> Self {
 28→        Self {
 29→            project_root: project_root.to_path_buf(),
 30→            args,
 31→        }
 32→    }
 33→
 34→    /// Get the project root path.
 35→    pub fn project_root(&self) -> &Path {
 36→        &self.project_root
 37→    }
 38→
 39→    /// Get the command arguments.
 40→    pub fn args(&self) -> &InitArgs {
 41→        &self.args
 42→    }
 43→
 44→    /// Check if config already exists.
 45→    fn config_exists(&self) -> bool {
 46→        self.project_root.join(".bivvy/config.yml").exists()
 47→    }
 48→
 49→    /// Create configuration content from selected steps with template info.
 50→    fn create_config(&self, steps: &[(&str, Option<&Template>)]) -> String {
 51→        let project_name = self
 52→            .project_root
 53→            .file_name()
 54→            .and_then(|n| n.to_str())
 55→            .unwrap_or("MyApp");
 56→
 57→        let mut config = format!(
 58→            "# Bivvy configuration for {project_name}\n\
 59→             # Docs: https://bivvy.dev/configuration\n\
 60→             #\n\
 61→             # Override any template field per-step:\n\
 62→             #   steps:\n\
 63→             #     example:\n\
 64→             #       template: bundler\n\
 65→             #       env:\n\
 66→             #         BUNDLE_WITHOUT: \"production\"\n\
 67→             #\n\
 68→             # Add custom steps:\n\
 69→             #   steps:\n\
 70→             #     setup_db:\n\
 71→             #       title: \"Set up database\"\n\
 72→             #       command: \"bin/rails db:setup\"\n\
 73→             #       completed_check:\n\
 74→             #         type: command_succeeds\n\
 75→             #         command: \"bin/rails db:version\"\n\
 76→             #\n\
 77→             # Create named workflows:\n\
 78→             #   workflows:\n\
 79→             #     ci:\n\
 80→             #       steps: [bundler, yarn]\n\
 81→             #       settings:\n\
 82→             #         default_output: quiet\n\
 83→             \n\
 84→             app_name: \"{project_name}\"\n\
 85→             \n\
 86→             settings:\n\
 87→             \x20 default_output: verbose  # verbose | quiet | silent\n\
 88→             \n\
 89→             steps:\n"
 90→        );
 91→
 92→        let step_names: Vec<&str> = steps.iter().map(|(name, _)| *name).collect();
 93→
 94→        for (name, template) in steps {
 95→            config.push_str(&format!("  {}:\n    template: {}\n", name, name));
 96→
 97→            if let Some(tmpl) = template {
 98→                // Show command
 99→                if let Some(ref cmd) = tmpl.step.command {
100→                    config.push_str(&format!("    # command: {}\n", cmd));
101→                }
102→
103→                // Show completed_check
104→                if let Some(ref check) = tmpl.step.completed_check {
105→                    Self::format_completed_check(&mut config, check);
106→                }
107→
108→                // Show watches
109→                if !tmpl.step.watches.is_empty() {
110→                    let watches: Vec<&str> = tmpl.step.watches.iter().map(|s| s.as_str()).collect();
111→                    config.push_str(&format!("    # watches: [{}]\n", watches.join(", ")));
112→                }
113→            }
114→
115→            config.push('\n');
116→        }
117→
118→        config.push_str("workflows:\n  default:\n    steps: ");
119→        config.push_str(&format!("[{}]\n", step_names.join(", ")));
120→
121→        config
122→    }
123→
124→    /// Format a completed_check as YAML comments.
125→    fn format_completed_check(config: &mut String, check: &CompletedCheck) {
126→        match check {
127→            CompletedCheck::FileExists { path } => {
128→                config.push_str("    # completed_check:\n");
129→                config.push_str("    #   type: file_exists\n");
130→                config.push_str(&format!("    #   path: \"{}\"\n", path));
131→            }
132→            CompletedCheck::CommandSucceeds { command } => {
133→                config.push_str("    # completed_check:\n");
134→                config.push_str("    #   type: command_succeeds\n");
135→                config.push_str(&format!("    #   command: \"{}\"\n", command));
136→            }
137→            _ => {}
138→        }
139→    }
140→
141→    /// Update gitignore to exclude local overrides.
142→    fn update_gitignore(&self, ui: &mut dyn UserInterface) -> Result<()> {
143→        let gitignore_entry = ".bivvy/config.local.yml";
144→        let gitignore_path = self.project_root.join(".gitignore");
145→
146→        if gitignore_path.exists() {
147→            let content = fs::read_to_string(&gitignore_path)?;
148→            if !content.contains(gitignore_entry) {
149→                let new_content = if content.ends_with('\n') {
150→                    format!("{}{}\n", content, gitignore_entry)
151→                } else {
152→                    format!("{}\n{}\n", content, gitignore_entry)
153→                };
154→                fs::write(&gitignore_path, new_content)?;
155→                ui.message("Added .bivvy/config.local.yml to .gitignore");
156→            }
157→        }
158→
159→        Ok(())
160→    }
161→}
162→
163→impl Command for InitCommand {
164→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
165→        // Check if config already exists
166→        if self.config_exists() && !self.args.force {
167→            ui.warning("Configuration already exists. Use --force to overwrite.");
168→            return Ok(CommandResult::failure(1));
169→        }
170→
171→        ui.show_header("Project Setup");
172→        ui.message("Scanning project...\n");
173→
174→        // Run detection
175→        let detection = DetectionRunner::run(&self.project_root);
176→
177→        // Show detected technologies
178→        if !detection.project.details.is_empty() {
179→            ui.message("Detected technologies:");
180→            for detail in &detection.project.details {
181→                ui.success(&format!(
182→                    "  {} - {}",
183→                    detail.name,
184→                    detail.details.join(", ")
185→                ));
186→            }
187→            ui.message("");
188→        }
189→
190→        // Show conflicts
191→        for conflict in &detection.conflicts {
192→            ui.warning(&conflict.message);
193→            ui.message(&format!("  Suggestion: {}", conflict.suggestion));
194→            ui.message("");
195→        }
196→
197→        // Collect steps to include
198→        let mut steps = Vec::new();
199→
200→        if self.args.minimal || !ui.is_interactive() {
201→            // Just use detected templates
202→            for suggestion in &detection.suggested_templates {
203→                steps.push(suggestion.name.clone());
204→            }
205→        } else if !detection.suggested_templates.is_empty() {
206→            // Interactive multi-select checklist
207→            ui.message("Use [space] to toggle, [a] to toggle all, [enter] to confirm\n");
208→
209→            let options: Vec<PromptOption> = detection
210→                .suggested_templates
211→                .iter()
212→                .map(|s| PromptOption {
213→                    label: format!("{} — {}", s.name, s.reason),
214→                    value: s.name.clone(),
215→                })
216→                .collect();
217→
218→            let all_values = detection
219→                .suggested_templates
220→                .iter()
221→                .map(|s| s.name.as_str())
222→                .collect::<Vec<_>>()
223→                .join(",");
224→
225→            let prompt = Prompt {
226→                key: "init_steps".to_string(),
227→                question: "Select steps to include".to_string(),
228→                prompt_type: PromptType::MultiSelect { options },
229→                default: Some(all_values),
230→            };
231→
232→            if let Ok(PromptResult::Strings(selected)) = ui.prompt(&prompt) {
233→                steps = selected;
234→            }
235→        }
236→
237→        // If no steps detected, create a minimal example
238→        if steps.is_empty() {
239→            steps.push("setup".to_string());
240→        }
241→
242→        // Load templates to enrich config output
243→        let loader = BuiltinLoader::new().ok();
244→        let steps_with_templates: Vec<(&str, Option<&Template>)> = steps
245→            .iter()
246→            .map(|name| {
247→                let template = loader.as_ref().and_then(|l| l.get(name));
248→                (name.as_str(), template)
249→            })
250→            .collect();
251→
252→        // Generate config
253→        let config = self.create_config(&steps_with_templates);
254→
255→        // Write config
256→        let bivvy_dir = self.project_root.join(".bivvy");
257→        fs::create_dir_all(&bivvy_dir)?;
258→        fs::write(bivvy_dir.join("config.yml"), &config)?;
259→
260→        // Update gitignore
261→        self.update_gitignore(ui)?;
262→
263→        ui.success("Created .bivvy/config.yml");
264→
265→        // Offer to run setup immediately (interactive only)
266→        if ui.is_interactive() {
267→            let prompt = Prompt {
268→                key: "run_after_init".to_string(),
269→                question: "Run setup now?".to_string(),
270→                prompt_type: PromptType::Select {
271→                    options: vec![
272→                        PromptOption {
273→                            label: "Yes".to_string(),
274→                            value: "yes".to_string(),
275→                        },
276→                        PromptOption {
277→                            label: "No".to_string(),
278→                            value: "no".to_string(),
279→                        },
280→                    ],
281→                },
282→                default: Some("yes".to_string()),
283→            };
284→
285→            if let Ok(PromptResult::String(answer)) = ui.prompt(&prompt) {
286→                if answer == "yes" {
287→                    ui.message("");
288→                    let run_cmd = RunCommand::new(&self.project_root, RunArgs::default());
289→                    return run_cmd.execute(ui);
290→                }
291→            }
292→        }
293→
294→        ui.show_hint(hints::after_init());
295→
296→        Ok(CommandResult::success())
297→    }
298→}
